class Reader:
    def __init__(self, data):
        self.data = data; self.pos = 0
    def take(self, n):
        b = self.data[self.pos:self.pos+n]
        if len(b) != n: raise EOFError(f'needed {n} at {self.pos}')
        self.pos += n; return b
