        elif op in (26,33): desc='%s A=%d C=%d' % (name,A,C)
        elif op in (27,28,29,30,34): desc='%s A=%d B=%d C=%d' % (name,A,B,C)
        elif op == 37: desc='%s A=%d B=%d' % (name,A,B)
        else: desc='%s A=%d B=%d C=%d Bx=%d sBx=%d' % (name,A,B,C,Bx,sBx)
        if op == 36: desc += ' proto_nups=%d' % p.protos[Bx].nups
        print('  '*depth + '  [%03d] line %-4s %s' % (i,line,desc))
    for j,sp in enumerate(p.protos):
        print()
        disasm(sp, depth+1)

