class LuaTable:
    def __init__(self):
        self.hash = {}

    def get(self, key):
        return self.hash.get(key)

    def set(self, key, value):
        if value is None:
            self.hash.pop(key, None)
        else:
            self.hash[key] = value

    def length(self):
        n = 0
        while self.get(float(n + 1)) is not None:
